function statusTag(status){return tag(({draft:'结构草稿',awaiting_assets:'制作准备',archived:'已归档',awaiting_source:'待数据入口',imported:'已收到导入'})[status]||status,status==='archived'?'':status==='awaiting_source'?'orange':'green');}
function queuePage(){const jobs=state.data.jobs.filter(j=>j.status!=='archived');return heading('制作队列','每个任务保留商品、参考、草稿与当前状态，修改后可以继续。',`<button class="btn primary" data-nav="studio">${icon('plus')}新建内容</button>`)+`<div class="banner">${icon('info')}当前支持分镜、图片、中文旁白与图卡试片。Seedance／MiniMax视频API待接入，试片不会标成模型视频。</div><div class="pipeline"><span class="current">结构草稿 ${jobs.filter(j=>j.status==='draft').length}</span>→<span class="current">制作准备 ${jobs.filter(j=>j.status==='awaiting_assets').length}</span>→<span>可渲染 0</span>→<span>成片 0</span></div>${jobs.map(j=>`<article class="job-card">${mark(j.title,1)}<div class="job-body"><h3>${esc(j.title)}</h3><div style="display:flex;gap:8px;margin:6px 0">${statusTag(j.status)}${tag(templates[j.template]||j.template)}</div><small>参考 ${esc(j.sample_id)} · 更新于 ${date(j.updated_at)}</small></div><div class="job-actions"><button class="btn small" data-production="${j.id}">打开视频分镜</button><button class="btn small" data-edit-job="${j.id}">编辑草稿</button><button class="btn small" data-download-job="${j.id}">${icon('download')}导出</button><button class="icon-btn" data-archive="${j.id}" aria-label="归档任务">${icon('check')}</button></div></article>`).join('')}${!jobs.length?`<section class="panel empty">${icon('layers')}<br>还没有制作任务。<br>选一本非教辅图书，直接打开原视频分镜。<br><button class="btn primary" data-nav="products" style="margin-top:18px">从选品开始 ${icon('arrow')}</button></section>`:''}`;}
function insightsPage(){const items=state.experiments;const latestByJob=new Map();for(const x of [...items].sort((a,b)=>(a.date+a.recordedAt).localeCompare(b.date+b.recordedAt)))latestByJob.set(x.jobId,x);const settled=[...latestByJob.values()].filter(x=>x.settledCommission!==''&&x.settledCommission!=null);const comparable=settled.filter(x=>x.cost!==''&&x.cost!=null);const contribution=comparable.reduce((sum,x)=>sum+Number(x.settledCommission)-Number(x.cost),0);return heading('经营复盘','把自己的平台结果，关联到具体稿件与制作任务。',`<button class="btn primary" data-action="experiment" ${!state.data.jobs.length?'disabled':''}>${icon('plus')}录入结果</button>`)+`<div class="stats compact">${[[items.length,'观察记录','按稿件与观察日期归档'],[settled.length,'已有结算的记录','未结算不计入收益'],[comparable.length?contribution.toFixed(2):'—','各任务最近记录贡献（元）','佣金与成本齐全时才计算'],['待接入','抖音后台自动回传','现在可以手动录入真实指标']].map(([v,l,f])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-value">${v}</div><div class="stat-foot">${f}</div></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>我们的实验结果</h2><small>灰豚估算不代替这里的订单与佣金</small></div>${items.length?`<div class="table-wrap"><table><thead><tr><th>任务 / 日期</th><th>播放</th><th>商品点击</th><th>支付订单</th><th>退款订单</th><th>结算佣金</th><th>录入成本</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(state.data.jobs.find(j=>j.id===x.jobId)?.title||x.jobId)}<div class="metric-caption">${esc(x.date)}</div></td>${['plays','clicks','paidOrders','refundOrders','settledCommission','cost'].map(k=>`<td>${x[k]===''||x[k]==null?'—':esc(x[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('chart')}<br>还没有自己的经营结果。<br>创建稿件并完成发布后，再录入对应指标。</div>`}</section><div class="callout">观察记录可能属于同一任务的不同时间点，不能简单累计为总收益。退款已反映在结算佣金时，不再次扣减；缺少的数据保留为空。</div>`;}
function settingsPage(){const s=latest();return heading('数据与设置','更新规则、数据快照与服务接入状态，在这里保持可见。',`<button class="btn primary" data-action="import">${icon('upload')}导入近30天榜单</button>`)+`<section class="panel"><div class="panel-head"><h2>每日选品更新</h2>${tag('调度已部署','green')}</div><div class="schedule-box"><div><small>更新频率</small><div class="schedule-number">每天<span>1次</span></div></div><div><small>数据窗口</small><div class="schedule-number">近30天<span>滚动观察</span></div></div><div><small>运行时间 · 上海</small><div class="schedule-number">09:00<span>每日检查数据入口</span></div></div></div><div class="integration-row"><div><strong>教辅与应试资料</strong><small>在导入、推荐与任务创建时强制排除，销量不能绕过此规则。</small></div>${tag('强制排除','green')}</div></section><section class="panel section-space"><div class="panel-head"><h2>数据与制作服务</h2></div>${[['灰豚榜单入口','支持导入官方Excel、CSV或JSON；每日自动拉取入口待接通。','可导入 / 自动采集待接','orange'],['参考正文','已接入本次研究保存的实际机器转写，可逐条阅读。','已接入','green'],['脚本生成','结构草稿可生成、编辑与保存；AI写作模型待配置。','模板可用','green'],['图片、中文旁白与试片','测试API生成图片与中文旁白；浏览器可串联15／30秒试片，视频模型接口后接。','测试已接入','green'],['经营结果','支持按任务录入真实指标；自动后台回传待接入。','可录入','green']].map(([title,desc,status,color])=>`<div class="integration-row"><div><strong>${title}</strong><small>${desc}</small></div>${tag(status,color)}</div>`).join('')}</section><section class="panel section-space"><div class="panel-head"><h2>已保存的数据快照</h2><small>当前截止 ${esc(s?.data_as_of||'未知')}</small></div><div class="table-wrap"><table><thead><tr><th>数据截止 / 窗口</th><th>来源</th><th>导入记录</th><th>排除 / 隔离</th><th>入库时间（上海）</th></tr></thead><tbody>${state.data.snapshots.map(x=>`<tr><td>${esc(x.data_as_of)} ${tag('近'+x.window_days+'天',x.window_days===30?'green':'orange')}</td><td>${esc(x.source)}</td><td>${x.imported}</td><td>${x.excluded} / ${x.quarantined}</td><td>${date(x.captured_at)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel section-space"><div class="panel-head"><h2>更新运行记录</h2><button class="btn small" data-action="sync">请求更新</button></div>${state.data.syncRuns.length?state.data.syncRuns.slice(0,6).map(r=>`<div class="integration-row"><div><strong>${date(r.requested_at)} · 拉取近${r.lookback_days}天</strong><small>${esc(r.message)}</small></div>${statusTag(r.status)}</div>`).join(''):'<div class="empty" style="padding:30px">暂无运行记录。每日调度会保留入口检查结果。</div>'}</section>`;}
function bindPage(){
 document.querySelector('#product-search')?.addEventListener('input',e=>{state.query=e.target.value;state.page=1;document.querySelector('#product-list').innerHTML=productTable(filteredProducts());});
 document.querySelector('#category-filter')?.addEventListener('change',e=>{state.category=e.target.value;state.page=1;document.querySelector('#product-list').innerHTML=productTable(filteredProducts());});
 document.querySelector('#scope-filter')?.addEventListener('change',e=>{state.filter=e.target.value;state.page=1;document.querySelector('#product-list').innerHTML=productTable(filteredProducts());});
 document.querySelector('#reference-search')?.addEventListener('change',e=>{state.query=e.target.value;renderPage();});
 document.querySelector('#studio-product')?.addEventListener('change',async e=>{try{if(!state.editBrief){if(e.target.value)await openReference(e.target.value);return;}collectBrief();if(e.target.value)await setSample(e.target.value);else{state.currentSample=null;state.currentProduct=null;state.brief={};state.jobId=null;state.draft='';}renderPage();}catch(error){toast(error.message);}});
 for(const id of ['genderId','ageId','taskId','templateId'])document.querySelector('#'+id)?.addEventListener('change',e=>{collectBrief();state.brief[id]=e.target.value;renderPage();});
 document.querySelectorAll('[name="openerId"]').forEach(el=>el.addEventListener('change',e=>{collectBrief();state.brief.openerId=e.target.value;renderPage();}));
 document.querySelector('#freeOpener')?.addEventListener('input',e=>{state.brief.freeOpener=e.target.value;document.querySelector('.brief-progress').textContent=remainingChoices().length?'还需选择：'+remainingChoices().join('、'):'选择已齐全，可以生成结构草稿。';document.querySelector('[data-action="generate"]').disabled=!briefReady();document.querySelector('[data-action="queue-draft"]').disabled=!state.jobId||!briefReady();});
 document.querySelector('#script')?.addEventListener('input',e=>state.draft=e.target.value);
}
function collectBrief(){for(const id of ['genderId','ageId','taskId','templateId','freeOpener']){const el=document.querySelector('#'+id);if(el)state.brief[id]=el.value;}const opener=document.querySelector('[name="openerId"]:checked');if(opener)state.brief.openerId=opener.value;const script=document.querySelector('#script');if(script)state.draft=script.value;}
async function setSample(id){const sample=await api('samples/'+encodeURIComponent(id));if(state.currentSample?.id!==id){state.brief={sourceVersion:sample.briefOptions?.sourceVersion,templateId:sample.briefOptions?.templates?.[0]?.id};state.jobId=null;state.draft='';}state.currentSample=sample;state.currentProduct=state.data.products.find(p=>p.samples.some(s=>s.id===id));}
function closeDetail(){document.querySelector('.details')?.remove();document.querySelector('.overlay')?.remove();}
async function showSample(id){const sample=await api('samples/'+encodeURIComponent(id));showDetail(state.data.products.find(p=>p.samples.some(s=>s.id===id)),sample);}
async function showProduct(key){const p=state.data.products.find(x=>x.key===key);if(!p)return;const sample=await api('samples/'+p.samples[0].id);showDetail(p,sample);}
function showDetail(p,s){closeDetail();const b=s.buyer;const div=document.createElement('div');div.className='overlay';div.dataset.action='close-detail';document.body.append(div);const detail=document.createElement('aside');detail.className='details';detail.setAttribute('aria-label','商品与参考详情');detail.innerHTML=`<header class="detail-head"><strong>商品与参考证据</strong><button class="icon-btn" data-action="close-detail" aria-label="关闭详情">${icon('close')}</button></header><div class="detail-body">${tag(p.category,'green')}<h2>${esc(p.product)}</h2><div class="facts"><div class="fact"><small>关联参考</small><strong>${p.samples.length} 条</strong></div><div class="fact"><small>当前参考销售估算</small><strong>${esc(s.sales_band)}</strong></div><div class="fact"><small>观察页面价</small><strong>${b?.observed_price!=null?'¥ '+b.observed_price:'尚未取得'}</strong></div><div class="fact"><small>公开佣金</small><strong>${b?.public_commission_pct!=null?b.public_commission_pct+'%':'尚未取得'}</strong></div></div><p class="detail-p">${esc(p.identity)}。目前均为研究候选，需核对商品用途、版本与素材后制作。</p><section class="detail-section"><h3>具体SKU的成交观察</h3>${b?.available_distribution?`<div style="display:flex;gap:8px;flex-wrap:wrap">${(b.summary||[]).map(t=>tag(t,'green')).join('')}</div><p class="detail-p">${esc(b.source_type)}。性别和年龄分别统计，不能合成精确交集。画像周期、样本量及原生八大人群占比未取得。</p>`:'<p class="detail-p">尚未取得可用成交分布。不要以粉丝、观众或视频场景代替实际购买画像。</p>'}${b?.source_url?`<a class="btn small" href="${esc(b.source_url)}" target="_blank" rel="noopener noreferrer">打开灰豚商品页 ${icon('external')}</a>`:''}</section><section class="detail-section"><h3>参考视频与口播正文</h3><p class="detail-p">${esc(s.id)} · ${esc(s.account)} · ${esc(s.published_at)}<br>来源窗口近${s.source_window}天 · 当前正文为机器未校对稿</p>${s.video_id?`<a class="btn small" href="https://www.douyin.com/video/${esc(s.video_id)}" target="_blank" rel="noopener noreferrer">打开抖音原视频 ${icon('external')}</a>`:''}<div class="reading-box" style="margin-top:15px">${esc(s.body||'正文待采集；目前只有来源字段，不能把标题作为口播。')}</div></section>${s.analysis?`<section class="detail-section"><h3>已有结构分析</h3><div class="reading-box analysis">${esc(s.analysis)}</div></section>`:''}<section class="detail-section"><h3>这个商品组的全部参考</h3>${p.samples.map(x=>`<div class="sample-mini"><div><strong>${esc(x.id)} · ${esc(x.account)}</strong><small>销售估算 ${esc(x.salesBand)} · ${x.hasBody?'机器正文可读':'正文待采集'}</small></div><button data-sample="${x.id}">查看正文</button></div>`).join('')}</section></div><footer class="detail-action"><button class="btn" data-favorite="${p.key}">${icon('star')}${p.favorite?'已收藏':'收藏商品'}</button><button class="btn primary" data-create="${s.id}">打开视频分镜 ${icon('arrow')}</button></footer>`;document.body.append(detail);detail.querySelector('[data-action="close-detail"]').focus();}
function openModal(title,content,footer=''){modal.className='';modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭窗口">${icon('close')}</button></div><div class="modal-body">${content}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;modal.showModal();}
let productionView=null;
function svgData(svg){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);}
function collectReferenceEdits(){const rows=[...modal.querySelectorAll('[data-reference-row]')];if(rows.length)productionView.referenceDrafts=rows.map(el=>({id:el.dataset.referenceRow,included:el.querySelector('[data-ref-included]').checked,vo:el.querySelector('[data-reference-vo]').value,visual:el.querySelector('[data-reference-visual]').value,kind:el.querySelector('[data-reference-kind]').value,selectionSet:true,...(el.querySelector('[data-reference-seconds]')?.value!==''?{seconds:Number(el.querySelector('[data-reference-seconds]').value)}:{})}));const instruction=modal.querySelector('#ai-instruction');if(instruction)productionView.aiInstruction=instruction.value;return productionView.referenceDrafts||productionView.pack.referenceEdits||[];}
function collectPlanChoices(){collectReferenceEdits();const p=productionView.pack,c={...p.planChoices,...productionView.pendingChoices,durationSeconds:Number(document.querySelector('#plan-duration')?.value||p.targetDurationSeconds),format:document.querySelector('#plan-format')?.value||p.format};const rows=[...document.querySelectorAll('[data-shot-choice]')];if(rows.length)c.shots=[...(c.shots||[]).filter(s=>!rows.some(r=>r.dataset.shotChoice===s.id)),...rows.map(el=>{const old=(c.shots||[]).find(s=>s.id===el.dataset.shotChoice)||{},seconds=el.querySelector('[data-shot-seconds]');return {id:el.dataset.shotChoice,enabled:el.querySelector('[data-shot-enabled]').checked,kind:el.querySelector('[data-shot-kind]').value,imageId:el.querySelector('[data-shot-image]').value,includeVO:el.querySelector('[data-shot-include-vo]').checked,vo:el.querySelector('[data-shot-vo]').value,visual:el.querySelector('[data-shot-visual]').value,...(seconds&&(old.seconds!=null||seconds.value!==seconds.dataset.autoSeconds)?{seconds:Number(seconds.value)}:{})};})];const refs=[...document.querySelectorAll('[data-ref-choice]')];if(refs.length)c.referenceChoices=Object.fromEntries(refs.map(el=>[el.dataset.refChoice,el.checked]));const vo=document.querySelector('#plan-vo');if(vo)c.narrationOverride=vo.value;return c;}
async function showProduction(id,refresh=false){const view=await api('jobs/'+id+'/production',refresh?'POST':'GET',refresh?{}:undefined);if(!view.pack){Object.assign(view,await api('jobs/'+id+'/production','POST',{}));}productionView={...view,tab:view.pack.referenceRows?.length?'reference':view.pack.scriptLocked?'shots':'voice'};openModal('视频分镜',productionHtml(productionView),`<button class="btn" data-action="refresh-production">按已保存稿件更新方案</button><button class="btn primary" data-action="download-production">下载完整素材包</button>`);modal.className='production-modal';updateSelectionCounts();}
async function ensurePlanSaved(){if(!productionView.isDirty)return;const tab=productionView.tab;const choices=collectPlanChoices();Object.assign(productionView,await api('jobs/'+productionView.pack.jobId+'/production','POST',{choices}));productionView.pendingChoices=null;productionView.isDirty=false;productionView.tab=tab;}
function updateSelectionCounts(){for(const scope of ['reference','shot']){const label=modal.querySelector('[data-selection-count="'+scope+'"]');if(!label)continue;const inputs=[...modal.querySelectorAll(scope==='reference'?'[data-ref-included]':'[data-shot-enabled]')];label.textContent='已选 '+inputs.filter(el=>el.checked).length+' / '+inputs.length+' 个';}}
function renderProduction(){modal.querySelector('.modal-body').innerHTML=productionHtml(productionView);updateSelectionCounts();}
function saveBlob(data,name,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function svgPng(svg){const img=new Image();img.src=svgData(svg);await img.decode();const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1920;canvas.getContext('2d').drawImage(img,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('PNG导出失败');return new Uint8Array(await blob.arrayBuffer());}
async function downloadProduction(){const p=productionView.pack,files={};for(const c of p.cards){files[c.name]=strToU8(c.svg);files[c.name.replace(/\.svg$/,'.png')]=await svgPng(c.svg);}files['VO旁白试稿.txt']=strToU8(p.narration);files['字幕估计节奏.srt']=strToU8(p.srt);files['分镜与提示词.txt']=strToU8(storyboardText(p));files['production.json']=strToU8(JSON.stringify(p,null,2));saveBlob(zipSync(files),'图书视频素材-'+p.sampleId+'.zip','application/zip');}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(Boolean))rows.push(row);return rows;}
function matrixToRows(matrix){const headers=matrix[0]?.map(x=>String(x??'').trim().replace(/^\uFEFF/,''))||[];return matrix.slice(1).filter(r=>r.some(x=>x!==null&&x!=='')).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i] instanceof Date?r[i].toISOString().slice(0,19).replace('T',' '):r[i]??''])));}
function showImport(){state.importRows=[];openModal('导入近30天灰豚榜单',`<p class="detail-p" style="margin-top:0">在灰豚选择近30天、图书类目后导出。导入会强制排除教辅，保留来源与每日快照。</p><div class="form-grid"><div class="form-field"><label for="import-asof">数据截止日期</label><input id="import-asof" type="date" value="${new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date())}"></div><div class="form-field"><label>榜单窗口</label><input value="近30天（固定）" disabled></div></div><div class="upload-area">${icon('upload')}<strong id="upload-title">选择灰豚导出文件</strong><p>支持 .xlsx、.csv、.json · 最多2500条</p><input type="file" id="import-file" accept=".xlsx,.csv,.json" aria-label="选择榜单文件"></div><div id="import-preview"></div><p class="error-text" id="import-error"></p><div class="callout">需要商品名称、播主、发布时间；视频ID缺失时保留待匹配身份。已有参考的机器正文不会因重新导入榜单而丢失。</div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="confirm-import" id="confirm-import" disabled>导入并筛除教辅</button>`);document.querySelector('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const preview=document.querySelector('#import-preview'),error=document.querySelector('#import-error');error.textContent='';preview.textContent='正在读取文件…';try{if(file.size>6_000_000)throw new Error('请使用6MB以内的导出文件');let rows;if(file.name.toLowerCase().endsWith('.xlsx'))rows=matrixToRows(await readXlsxFile(file));else if(file.name.toLowerCase().endsWith('.csv'))rows=matrixToRows(parseCSV(await file.text()));else{const parsed=JSON.parse(await file.text());rows=Array.isArray(parsed)?parsed:parsed.records||parsed.rows;}if(!Array.isArray(rows)||!rows.length||rows.length>2500)throw new Error('需要1至2500条有效记录');state.importRows=rows;const eligible=rows.filter(r=>normalizeRow(r).scope.allowed);document.querySelector('#upload-title').textContent=file.name;preview.innerHTML=`<div style="display:flex;gap:8px;margin-bottom:13px">${tag('读取 '+rows.length+' 条')}${tag('候选 '+eligible.length+' 条','green')}${tag('排除 '+(rows.length-eligible.length)+' 条','orange')}</div><div class="preview-table"><table><tbody>${rows.slice(0,4).map(r=>{const n=normalizeRow(r);return `<tr><td>${esc(n.product||'缺少商品字段')}</td><td>${tag(n.scope.allowed?'候选':'已排除',n.scope.allowed?'green':'orange')}</td></tr>`;}).join('')}</tbody></table></div>`;document.querySelector('#confirm-import').disabled=false;}catch(err){preview.textContent='';error.textContent=err.message;document.querySelector('#confirm-import').disabled=true;}});}
function download(text,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function renderGraphicsPreview(withVO=false){
 await ensurePlanSaved();
 if(!window.MediaRecorder)throw new Error('当前浏览器不支持视频录制，可下载图卡素材包');
 const p=productionView.pack,canvas=document.createElement('canvas');canvas.width=720;canvas.height=1280;const ctx=canvas.getContext('2d');
 const images=await Promise.all(p.cards.map(async c=>{const img=new Image();img.src=svgData(c.svg);await img.decode();return {id:c.id,img};}));for(const media of p.generated||[]){if(media.kind==='image'){const img=new Image();img.src=media.url;await img.decode();images.push({id:media.shotId,img});}}
 const modelClips=[];
 for(const task of productionView.modelTasks||[]){if(task.status==='succeeded'&&task.sourceHash===p.planHash&&task.outputUrl){const clip=document.createElement('video');clip.muted=true;clip.playsInline=true;clip.preload='auto';clip.src='/api/model-tasks/'+task.id+'/media';await new Promise((resolve,reject)=>{clip.addEventListener('loadeddata',resolve,{once:true});clip.addEventListener('error',()=>reject(new Error('模型片段读取失败，未标记合成成功')),{once:true});clip.load();});modelClips.push({shotId:task.shotId,clip});}}
 let playingShot=null;
 const canvasStream=canvas.captureStream(24);let audioContext,source,audioStream;
 if(withVO){const media=await api('jobs/'+p.jobId+'/voice','POST',{});audioContext=new AudioContext();await audioContext.resume();const buffer=await audioContext.decodeAudioData(await (await fetch(media.url)).arrayBuffer());const rate=buffer.duration/p.targetDurationSeconds;if(rate<0.5||rate>2)throw new Error('当前VO无法自然放进目标时长，请缩短或扩写后重试');const dest=audioContext.createMediaStreamDestination();source=audioContext.createBufferSource();source.buffer=buffer;source.playbackRate.value=rate;source.connect(dest);audioStream=dest.stream;}
 const stream=new MediaStream([...canvasStream.getVideoTracks(),...(audioStream?.getAudioTracks()||[])]),mime=['video/mp4','video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw new Error('当前浏览器没有可用的视频编码器');
 const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:900000,audioBitsPerSecond:64000}),data=[];
 recorder.ondataavailable=e=>{if(e.data.size)data.push(e.data);};const stopped=new Promise(resolve=>recorder.onstop=resolve);const start=performance.now();
 const status=modal.querySelector('#graphics-render-state');status.textContent='正在生成图卡视频，请保持页面打开…';
 let animation;const draw=()=>{const elapsed=Math.min((performance.now()-start)/1000,p.targetDurationSeconds);const shot=p.shots.find(s=>elapsed>=s.startSeconds&&elapsed<s.endSeconds)||p.shots[p.shots.length-1];const image=images.find(i=>i.id===shot.id)||images.find(i=>i.id===shot.imageId)||images[0];ctx.fillStyle='#f4f2e8';ctx.fillRect(0,0,720,1280);const videoSource=modelClips.find(v=>v.shotId===shot.id);if(playingShot!==shot.id){modelClips.forEach(v=>v.clip.pause());if(videoSource){videoSource.clip.currentTime=0;videoSource.clip.play().catch(()=>{});}playingShot=shot.id;}ctx.drawImage(videoSource?.clip||image.img,0,0,720,1280);ctx.fillStyle='rgba(12,25,18,.82)';ctx.fillRect(24,1050,672,170);ctx.fillStyle='#fff';ctx.font='24px sans-serif';const chars=Array.from(shot.vo);for(let i=0;i<Math.min(3,Math.ceil(chars.length/24));i++)ctx.fillText(chars.slice(i*24,(i+1)*24).join(''),42,1094+i*40);status.textContent='正在生成 '+Math.floor(elapsed)+' / '+p.targetDurationSeconds+'秒';if(elapsed<p.targetDurationSeconds)animation=requestAnimationFrame(draw);else recorder.stop();};
 draw();recorder.start(1000);if(source)source.start();await stopped;cancelAnimationFrame(animation);stream.getTracks().forEach(t=>t.stop());modelClips.forEach(v=>v.clip.pause());if(audioContext)await audioContext.close();const blob=new Blob(data,{type:mime});const url=URL.createObjectURL(blob);const video=modal.querySelector('#graphics-render-video');video.src=url;video.hidden=false;status.textContent=withVO?'图卡 + VO视频已生成（不是视频模型成片）':'图卡视频已生成（无VO音频；不是视频模型成片）';const saved=await api('jobs/'+p.jobId+'/previews','POST',{planHash:p.planHash,mime,hasVO:withVO,base64:toBase64(new Uint8Array(await blob.arrayBuffer()))});productionView.pack.savedPreview=saved;renderProduction();toast('试片已录制并保存，可以下载');
}
function showExperiment(){openModal('录入真实经营结果',`<div class="form-field"><label for="experiment-job">对应制作任务</label><select id="experiment-job">${state.data.jobs.map(j=>`<option value="${j.id}">${esc(j.title)}</option>`).join('')}</select></div><div class="form-field"><label for="experiment-date">观察日期</label><input id="experiment-date" type="date" value="${new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date())}"></div><div class="form-grid">${[['plays','播放量'],['clicks','商品点击'],['paidOrders','支付订单'],['refundOrders','退款订单'],['settledCommission','实际结算佣金（元）'],['cost','可归属成本（元）']].map(([id,label])=>`<div class="form-field"><label for="exp-${id}">${label}</label><input id="exp-${id}" type="number" min="0" step="${id==='cost'||id==='settledCommission'?'0.01':'1'}" placeholder="未取得则留空"></div>`).join('')}</div><div class="form-field"><label for="experiment-note">观察说明</label><textarea id="experiment-note" placeholder="填写数据来源、窗口、是否结算成熟等"></textarea></div><div class="callout">同任务不同观察日期的累计指标不要重复加总。未取得字段留空，不能补成0。</div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-experiment">保存结果</button>`);}
